-- Disposable synthetic identities, no production data; always rolled back.
begin;
create schema fk_stab_test;
grant usage on schema fk_stab_test to authenticated;
create function fk_stab_test.ok(v boolean,label text) returns void language plpgsql as $$
begin if v is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function fk_stab_test.rejected(statement text) returns boolean language plpgsql as $$
begin execute statement;return false;exception when others then return true;end $$;
grant execute on all functions in schema fk_stab_test to authenticated;
insert into auth.users(id) values ('f1111111-1111-4111-8111-111111111111'),('f2222222-2222-4222-8222-222222222222'),('f3333333-3333-4333-8333-333333333333'),('f4444444-4444-4444-8444-444444444444');
insert into auth.sessions(id,user_id) select id,id from auth.users where id::text like 'f%';
insert into folkoop_private.pilots(user_id) select id from auth.users where id::text like 'f%';
set local role authenticated;
select set_config('request.jwt.claim.sub','f1111111-1111-4111-8111-111111111111',true);
select set_config('request.jwt.claims','{"sub":"f1111111-1111-4111-8111-111111111111","session_id":"f1111111-1111-4111-8111-111111111111"}',true);
select public.fk_save_profile('Synthetic person 0','','',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f2222222-2222-4222-8222-222222222222',true);
select set_config('request.jwt.claims','{"sub":"f2222222-2222-4222-8222-222222222222","session_id":"f2222222-2222-4222-8222-222222222222"}',true);
select public.fk_save_profile('Synthetic person 1','','',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f3333333-3333-4333-8333-333333333333',true);
select set_config('request.jwt.claims','{"sub":"f3333333-3333-4333-8333-333333333333","session_id":"f3333333-3333-4333-8333-333333333333"}',true);
select public.fk_save_profile('Synthetic person 2','','',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f4444444-4444-4444-8444-444444444444',true);
select set_config('request.jwt.claims','{"sub":"f4444444-4444-4444-8444-444444444444","session_id":"f4444444-4444-4444-8444-444444444444"}',true);
select public.fk_save_profile('Synthetic person 3','','',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f1111111-1111-4111-8111-111111111111',true);
select set_config('request.jwt.claims','{"sub":"f1111111-1111-4111-8111-111111111111","session_id":"f1111111-1111-4111-8111-111111111111"}',true);
select set_config('test.chat',public.fk_start_direct('f2222222-2222-4222-8222-222222222222')::text,true);
reset role;
update public.fk_conversation_members set last_read_at='2000-01-01' where conversation_id=current_setting('test.chat')::uuid;
insert into public.fk_messages(id,conversation_id,author_id,body,created_at)
select ('a0000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,current_setting('test.chat')::uuid,'f1111111-1111-4111-8111-111111111111','message '||n,'2026-11-01T12:00:00.123456Z'::timestamptz from generate_series(1,101) n;
set local role authenticated;
select set_config('request.jwt.claim.sub','f2222222-2222-4222-8222-222222222222',true);
select set_config('request.jwt.claims','{"sub":"f2222222-2222-4222-8222-222222222222","session_id":"f2222222-2222-4222-8222-222222222222"}',true);
select fk_stab_test.ok((select unread_count=101 from public.fk_chat_inbox() where conversation_id=current_setting('test.chat')::uuid),'101 equal-time messages start unread');
select public.fk_mark_messages_read(current_setting('test.chat')::uuid,array(select id from public.fk_messages where conversation_id=current_setting('test.chat')::uuid order by created_at desc,id desc limit 100));
select fk_stab_test.ok((select unread_count=1 from public.fk_chat_inbox() where conversation_id=current_setting('test.chat')::uuid),'unloaded older message remains unread');
reset role;
-- Arrives after the page was fetched; identical timestamp and lower UUID must not be swallowed.
insert into public.fk_messages values('90000000-0000-4000-8000-000000000001',current_setting('test.chat')::uuid,'f1111111-1111-4111-8111-111111111111','racing arrival','2026-11-01T12:00:00.123456Z');
set local role authenticated;
select set_config('request.jwt.claim.sub','f2222222-2222-4222-8222-222222222222',true);
select set_config('request.jwt.claims','{"sub":"f2222222-2222-4222-8222-222222222222","session_id":"f2222222-2222-4222-8222-222222222222"}',true);
select public.fk_mark_messages_read(current_setting('test.chat')::uuid,array['a0000000-0000-4000-8000-000000000101'::uuid]);
select fk_stab_test.ok((select unread_count=2 from public.fk_chat_inbox() where conversation_id=current_setting('test.chat')::uuid),'race survives repeated receipt with same timestamp');
select public.fk_send_message(current_setting('test.chat')::uuid,'My reply');
select public.fk_mark_chat_read(current_setting('test.chat')::uuid);
select fk_stab_test.ok((select unread_count=2 from public.fk_chat_inbox() where conversation_id=current_setting('test.chat')::uuid),'sending and legacy read do not clear unseen messages');
select fk_stab_test.ok((select count(*)=100 from public.fk_message_reads),'read retries are idempotent');
select fk_stab_test.ok(fk_stab_test.rejected(format('select public.fk_mark_messages_read(%L,array[]::uuid[])',current_setting('test.chat'))),'empty receipt batch rejected');
select fk_stab_test.ok(fk_stab_test.rejected('delete from public.fk_message_reads'),'client cannot forge or delete read state directly');
select fk_stab_test.ok(fk_stab_test.rejected(format('select public.fk_mark_messages_read(%L,array_fill(''a0000000-0000-4000-8000-000000000101''::uuid,array[101]))',current_setting('test.chat'))),'oversized receipt batch rejected');
select fk_stab_test.ok(fk_stab_test.rejected(format('select public.fk_mark_messages_read(%L,array[null]::uuid[])',current_setting('test.chat'))),'null receipt id rejected');
set local role authenticated;
select set_config('request.jwt.claim.sub','f4444444-4444-4444-8444-444444444444',true);
select set_config('request.jwt.claims','{"sub":"f4444444-4444-4444-8444-444444444444","session_id":"f4444444-4444-4444-8444-444444444444"}',true);
select fk_stab_test.ok((select count(*)=0 from public.fk_message_reads),'receipt privacy excludes outsider');
select fk_stab_test.ok(fk_stab_test.rejected(format('select public.fk_mark_messages_read(%L,array[''a0000000-0000-4000-8000-000000000101''::uuid])',current_setting('test.chat'))),'outsider cannot mark another chat read');
set local role authenticated;
select set_config('request.jwt.claim.sub','f2222222-2222-4222-8222-222222222222',true);
select set_config('request.jwt.claims','{"sub":"f2222222-2222-4222-8222-222222222222","session_id":"f2222222-2222-4222-8222-222222222222"}',true);
select public.fk_mark_messages_read(current_setting('test.chat')::uuid,array['90000000-0000-4000-8000-000000000001'::uuid,'a0000000-0000-4000-8000-000000000001'::uuid]);
select fk_stab_test.ok((select unread_count=0 from public.fk_chat_inbox() where conversation_id=current_setting('test.chat')::uuid),'only exact remaining messages clear unread');
reset role;
select fk_stab_test.ok(not has_function_privilege('anon','public.fk_mark_messages_read(uuid,uuid[])','execute'),'anonymous RPC execution denied');
delete from auth.users where id='f2222222-2222-4222-8222-222222222222';
select fk_stab_test.ok((select count(*)=0 from public.fk_message_reads where user_id='f2222222-2222-4222-8222-222222222222'),'closure cascades personal receipts');
rollback;
